using Microsoft.AspNetCore.Mvc;using Orchestration.API.Engineering.Services;
namespace Orchestration.API.Engineering.Controllers;
[ApiController][Route("api/engineering/jobs")]public sealed class EngineeringJobsController:ControllerBase{readonly IEngineeringJobStore jobs;readonly IEngineeringCancellationRegistry cancellations;public EngineeringJobsController(IEngineeringJobStore jobs,IEngineeringCancellationRegistry cancellations){this.jobs=jobs;this.cancellations=cancellations;}[HttpGet("{jobId}")]public IActionResult Get(string jobId)=>jobs.TryGet(jobId,out var job)?Ok(job):jobs.LookupStatus(jobId)=="expired"?StatusCode(410,new{code="job-expired",message="Job has expired."}):NotFound(new{code="job-not-found",message="Job was not found."});[HttpPost("{jobId}/cancel")]public IActionResult Cancel(string jobId){var result=cancellations.Cancel(jobId);return result.Code switch{"job-not-found"=>NotFound(result),"job-already-completed" or "job-already-cancelled" or "cancellation-unsupported"=>Conflict(result),_=>result.Accepted?Accepted(result):StatusCode(500,result)};}}
